/**
* Media upload, list, delete, and provider APIs
*/
/**
* Maximum length of the media filename search term. Mirrors the server-side
* zod schema (`q: z.string().trim().min(1).max(200)`); keep in sync.
*/
const MEDIA_SEARCH_MAX_LENGTH = 200;
/** Trim and clamp a search term to the server-accepted range. */
function normalizeMediaSearch(value) {
	return (value ?? "").trim().slice(0, MEDIA_SEARCH_MAX_LENGTH);
}
/**
* Fetch media list
*/
async function fetchMediaList(options) {
	const params = new URLSearchParams();
	if (options?.cursor) params.set("cursor", options.cursor);
	if (options?.limit) params.set("limit", String(options.limit));
	if (options?.mimeType) {
		const value = Array.isArray(options.mimeType) ? options.mimeType.join(",") : options.mimeType;
		if (value) params.set("mimeType", value);
	}
	if (options?.search) {
		const q = normalizeMediaSearch(options.search);
		if (q) params.set("q", q);
	}
	return parseApiResponse(await apiFetch(`${API_BASE}/media${params.toString() ? `?${params}` : ""}`), "Failed to fetch media");
}
/**
* Try to get a signed upload URL
* Returns null if signed URLs are not supported (e.g., local storage)
*/
async function getUploadUrl(file, opts) {
	try {
		const response = await apiFetch(`${API_BASE}/media/upload-url`, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				filename: file.name,
				contentType: file.type,
				size: file.size,
				...opts?.fieldId ? { fieldId: opts.fieldId } : {}
			})
		});
		if (response.status === 501) return null;
		return parseApiResponse(response, "Failed to get upload URL");
	} catch (error) {
		if (error instanceof TypeError && error.message.includes("fetch")) return null;
		throw error;
	}
}
/**
* Confirm upload after uploading to signed URL
*/
async function confirmUpload(mediaId, metadata) {
	return (await parseApiResponse(await apiFetch(`${API_BASE}/media/${mediaId}/confirm`, {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify(metadata || {})
	}), "Failed to confirm upload")).item;
}
/**
* Upload directly to signed URL
*/
async function uploadToSignedUrl(file, uploadInfo) {
	const response = await fetch(uploadInfo.uploadUrl, {
		method: uploadInfo.method,
		headers: {
			...uploadInfo.headers,
			"Content-Type": file.type
		},
		body: file
	});
	if (!response.ok) await throwResponseError(response, i18n._({
		id: "4Gz2wC",
		message: "Failed to upload file"
	}));
}
/**
* Get image dimensions from a file
*/
async function getImageDimensions(file) {
	if (!file.type.startsWith("image/")) return null;
	return new Promise((resolve) => {
		const img = new Image();
		img.onload = () => {
			resolve({
				width: img.naturalWidth,
				height: img.naturalHeight
			});
			URL.revokeObjectURL(img.src);
		};
		img.onerror = () => {
			resolve(null);
			URL.revokeObjectURL(img.src);
		};
		img.src = URL.createObjectURL(file);
	});
}
/**
* Upload media file via direct upload (legacy/local storage)
*/
async function uploadMediaDirect(file, opts) {
	const dimensions = await getImageDimensions(file);
	const formData = new FormData();
	formData.append("file", file);
	if (dimensions?.width) formData.append("width", String(dimensions.width));
	if (dimensions?.height) formData.append("height", String(dimensions.height));
	if (opts?.fieldId) formData.append("fieldId", opts.fieldId);
	return (await parseApiResponse(await apiFetch(`${API_BASE}/media`, {
		method: "POST",
		body: formData
	}), "Failed to upload media")).item;
}
/**
* Upload media file
*
* Tries signed URL upload first (for S3/R2 storage), falls back to direct upload
* (for local storage) if signed URLs are not supported.
*/
async function uploadMedia(file, opts) {
	const uploadInfo = await getUploadUrl(file, opts);
	if (!uploadInfo) return uploadMediaDirect(file, opts);
	await uploadToSignedUrl(file, uploadInfo);
	const dimensions = await getImageDimensions(file);
	return confirmUpload(uploadInfo.mediaId, {
		size: file.size,
		width: dimensions?.width,
		height: dimensions?.height
	});
}
/**
* Delete media
*/
async function deleteMedia(id) {
	const response = await apiFetch(`${API_BASE}/media/${id}`, { method: "DELETE" });
	if (!response.ok) await throwResponseError(response, i18n._({
		id: "YjAWKL",
		message: "Failed to delete media"
	}));
}
